<?php
session_start();
if (empty($_SESSION['User_id']) || strtolower((string)($_SESSION['User_role'] ?? '')) !== 'collector') { header('Location: login.php'); exit; }
require_once __DIR__ . '/../config/dashboard.php';
$uid=(int)$_SESSION['User_id'];
$stmt=$conn->prepare('SELECT fname,lname,email,phone,address FROM users WHERE ID=?');$stmt->bind_param('i',$uid);$stmt->execute();$user=$stmt->get_result()->fetch_assoc()?:[];
$stmt=$conn->prepare('SELECT schedule_id,area_purok,schedule_date,start_time,end_time,waste_type,status FROM collection_schedules WHERE collector_id=? ORDER BY schedule_date DESC,start_time DESC');$stmt->bind_param('i',$uid);$stmt->execute();$schedules=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);
$stmt=$conn->prepare('SELECT observation_id,area_purok,location_details,proper_bins,total_bins,status,created_at FROM segregation_observations WHERE collector_id=? ORDER BY created_at DESC LIMIT 30');$stmt->bind_param('i',$uid);$stmt->execute();$observations=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);
$residents=$conn->query("SELECT ID,fname,lname,address FROM users WHERE LOWER(role)='resident' AND LOWER(status)='active' ORDER BY fname,lname")->fetch_all(MYSQLI_ASSOC);
$open=count(array_filter($schedules,fn($s)=>in_array($s['status'],['scheduled','in_progress'],true)));$notice=dashboard_notice();
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Collector dashboard – BarangayEcoCare</title><link rel="stylesheet" href="https://fonts.googleapis.com/css2?family=Outfit:wght@400;500;600;700&display=swap"><link rel="stylesheet" href="../style/global.css"><link rel="stylesheet" href="../style/dashboard.css"></head><body><div class="shell"><aside class="sidebar"><div><a href="../index.php" class="logo">Barangay<b>EcoCare</b></a><p class="ws">Collector workspace</p></div><nav class="nav"><a href="#v1">My schedule</a><a href="#v2">Segregation observations</a><a href="#v3">Profile</a></nav><div class="me"><div class="me-info"><span class="avatar"><?=e(strtoupper(substr($user['fname']??'C',0,1)))?></span><div><?=e(($user['fname']??'').' '.($user['lname']??''))?><small>Garbage Collector</small></div></div><a href="logout.php" class="btn">Log out</a></div></aside><main class="main"><div class="views"><?php if($notice):?><p class="notice" role="status"><?=e($notice)?></p><?php endif;?>
<section class="view" id="v1"><h1>My collection schedule</h1><p class="sub">Schedules assigned to your account by barangay staff.</p><div class="grid g3"><article class="card stat"><small>Assigned routes</small><b><?=count($schedules)?></b></article><article class="card stat"><small>Remaining routes</small><b><?=$open?></b></article><article class="card stat"><small>Completed routes</small><b><?=count($schedules)-$open?></b></article></div><article class="card" style="margin-top:var(--gap)"><ul class="rows"><?php if(!$schedules):?><li><span class="muted">No routes are assigned to you yet. Contact an official to be assigned to a schedule.</span></li><?php else:foreach($schedules as $s):?><li><div><strong><?=e($s['area_purok'])?> · <?=e($s['waste_type'])?></strong><small><?=e(date('D, M j, Y',strtotime($s['schedule_date'])))?><?= $s['start_time']?' · '.e(date('g:i A',strtotime($s['start_time']))):''?><?= $s['end_time']?'–'.e(date('g:i A',strtotime($s['end_time']))):''?></small></div><?php if(in_array($s['status'],['scheduled','in_progress'],true)):?><form action="dashboard-action.php" method="post"><?php dashboard_form_token();?><input type="hidden" name="action" value="complete_schedule"><input type="hidden" name="section" value="v1"><input type="hidden" name="schedule_id" value="<?=(int)$s['schedule_id']?>"><button class="btn btn-primary btn-sm">Mark complete</button></form><?php else:?><span class="badge b-done">Completed</span><?php endif;?></li><?php endforeach;endif;?></ul></article></section>
<section class="view" id="v2"><h1>Segregation observations</h1><p class="sub">Record the bin check and resident. An official reviews the evidence and awards any points.</p><div class="grid g2" style="align-items:start"><form class="card" action="dashboard-action.php" method="post" enctype="multipart/form-data"><?php dashboard_form_token();?><input type="hidden" name="action" value="submit_observation"><input type="hidden" name="section" value="v2"><label class="field"><span>Resident</span><select name="resident_id" required><option value="">Choose resident</option><?php foreach($residents as $r):?><option value="<?=(int)$r['ID']?>"><?=e($r['fname'].' '.$r['lname'].' · '.$r['address'])?></option><?php endforeach;?></select></label><label class="field"><span>Purok / area</span><input name="area_purok" required placeholder="Purok 5"></label><label class="field"><span>Stop / location</span><input name="location_details" required placeholder="Near the barangay hall"></label><div class="field-row"><label class="field"><span>Properly sorted bins</span><input type="number" name="proper_bins" min="0" required></label><label class="field"><span>Total bins checked</span><input type="number" name="total_bins" min="1" required></label></div><label class="field"><span>Notes</span><textarea name="notes" maxlength="3000"></textarea></label><label class="field"><span>Photo evidence (optional, max 5 MB)</span><input type="file" name="photo" accept="image/jpeg,image/png,image/webp"></label><button class="btn btn-primary btn-block">Submit observation</button></form><article class="card"><h2>My recent observations</h2><ul class="rows"><?php if(!$observations):?><li><span class="muted">No observations submitted yet.</span></li><?php else:foreach($observations as $o):?><li><div><strong><?=e($o['area_purok'])?> · <?=e($o['location_details'])?></strong><small><?= (int)$o['proper_bins']?> of <?= (int)$o['total_bins']?> bins properly sorted · <?=e(date('M j, Y',strtotime($o['created_at'])))?></small></div><span class="badge b-pending"><?=e(ucfirst($o['status']))?></span></li><?php endforeach;endif;?></ul></article></div></section>
<section class="view" id="v3"><h1>My profile</h1><div class="grid g2"><form class="card" action="dashboard-action.php" method="post"><?php dashboard_form_token();?><input type="hidden" name="action" value="update_profile"><input type="hidden" name="section" value="v3"><?php foreach(['fname'=>'First name','lname'=>'Last name','email'=>'Email','phone'=>'Phone','address'=>'Address'] as $key=>$label):?><label class="field"><span><?=e($label)?></span><input name="<?=e($key)?>" value="<?=e($user[$key]??'')?>" <?=$key==='email'?'type="email" required':''?> <?=$key==='fname'||$key==='lname'?'required':''?>></label><?php endforeach;?><button class="btn btn-primary">Save profile</button></form><form class="card" action="dashboard-action.php" method="post"><?php dashboard_form_token();?><input type="hidden" name="action" value="change_password"><input type="hidden" name="section" value="v3"><label class="field"><span>New password</span><input type="password" name="password" minlength="8" required></label><label class="field"><span>Confirm password</span><input type="password" name="confirm" minlength="8" required></label><button class="btn btn-primary">Change password</button></form></div></section>
</div></main></div></body></html>
